import * as T from './vendor/three.module.js';
import {WAYPOINTS,RUNWAY} from './flight-model.js';
import {elevation,routePosition} from './geography.js';
const material=(color)=>new T.MeshStandardMaterial({color,roughness:.85});
function part(g,geometry,color,x=0,y=0,z=0){const m=new T.Mesh(geometry,material(color));m.position.set(x,y,z);g.add(m);return m;}
const box=(g,w,h,d,c,x=0,y=0,z=0)=>part(g,new T.BoxGeometry(w,h,d),c,x,y,z);
const cyl=(g,r1,r2,h,c,x=0,y=0,z=0)=>part(g,new T.CylinderGeometry(r1,r2,h,12),c,x,y,z);
function beam(g,a,b,r,c){const v1=new T.Vector3(...a),v2=new T.Vector3(...b),m=cyl(g,r,r,v1.distanceTo(v2),c);m.position.copy(v1).add(v2).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v2.sub(v1).normalize());return m;}
export const LANDMARK_NAMES=['东方明珠 · 上海中心','东京塔 · 富士山','中银大厦 · 维港','滨海湾金沙','悉尼歌剧院','埃菲尔铁塔','大本钟 · 伦敦眼','自由女神像','金门大桥'];
export function landmark(index){const g=new T.Group(),red=0xc86543,white=0xf7f0d8,steel=0x6298a6;
if(index===0){cyl(g,9,17,230,0x99a8ad,0,115);[80,185].forEach((y,i)=>part(g,new T.SphereGeometry(i?26:36,24,16),0xda6f87,0,y));cyl(g,1,6,90,white,0,270);[-1,1].forEach(x=>beam(g,[x*36,0,12],[0,100,0],7,0xb3bcb3));for(let i=0;i<12;i++){const b=box(g,48-i*1.8,23,48-i*1.8,steel,110,i*23+12,-20);b.rotation.y=i*.045;}}
if(index===1||index===5){const h=index===1?300:270,c=index===1?red:0x9f8060;for(const x of [-1,1])for(const z of [-1,1]){beam(g,[x*55,0,z*55],[x*14,h*.65,z*14],5,c);beam(g,[x*14,h*.65,z*14],[0,h,0],3,c);}for(let i=1;i<8;i++){const y=i*h/9,s=110*(1-y/h);box(g,s,5,s,i%2&&index===1?white:c,0,y);for(const z of [-1,1]){beam(g,[-s/2,y,z*s/2],[s*.35,y+30,z*s*.35],2,c);beam(g,[s/2,y,z*s/2],[-s*.35,y+30,z*s*.35],2,c)}}cyl(g,1,3,45,c,0,h+15);if(index===1){const mountain=part(g,new T.ConeGeometry(700,850,64),0x728b94,-2000,330,-900);part(g,new T.ConeGeometry(210,255,64),0xf4f4ed,-2000,630,-900);}}
if(index===2){for(let i=0;i<3;i++){const h=160+i*60;box(g,40,h,40,steel,i*37,h/2,0);beam(g,[i*37-20,0,21],[i*37+20,h,21],2,white);beam(g,[i*37+20,0,21],[i*37-20,h,21],2,white);}cyl(g,1,2,50,white,74,310);}
if(index===3){[-70,0,70].forEach(x=>{box(g,38,165,55,0xa5c9c7,x,82);for(let i=1;i<16;i++)box(g,40,1.2,57,white,x,i*10)});const roof=part(g,new T.SphereGeometry(1,32,16),0x437f50,0,174);roof.scale.set(125,12,40);box(g,225,6,22,0x40b9d0,0,184,-8);}
if(index===4){box(g,220,10,140,0xc8b18c,0,5);for(let i=0;i<6;i++){const sail=part(g,new T.SphereGeometry(1,32,20,0,Math.PI),white,(i%3-1)*60,18,Math.floor(i/3)*55-30);sail.scale.set(40,65+(i%3)*18,40);sail.rotation.z=(i%3-1)*.3;sail.rotation.x=-.25;}}
if(index===6){box(g,45,170,45,0xb59764,0,85);box(g,51,35,51,0xd7c99a,0,175);part(g,new T.ConeGeometry(38,65,4),0x596f66,0,225);for(const z of [-26,26]){const face=part(g,new T.CircleGeometry(13,32),white,0,177,z);if(z<0)face.rotation.y=Math.PI;box(g,2,10,2,0x293d42,0,181,z);box(g,8,2,2,0x293d42,4,177,z);}const wheel=part(g,new T.TorusGeometry(95,3,8,72),white,210,105);for(let i=0;i<16;i++){const a=i/16*Math.PI*2;beam(g,[210,105,0],[210+95*Math.cos(a),105+95*Math.sin(a),0],.7,white);box(g,10,9,9,0x9ebdc7,210+95*Math.cos(a),105+95*Math.sin(a));}beam(g,[170,0,15],[210,105,0],5,white);beam(g,[250,0,15],[210,105,0],5,white);}
if(index===7){box(g,60,40,60,0xb7a483,0,20);cyl(g,13,28,95,0x6ca492,0,88);part(g,new T.SphereGeometry(12,16,12),0x6ca492,0,147);beam(g,[10,120,0],[32,175,0],6,0x6ca492);cyl(g,3,4,25,0x826b43,32,185);part(g,new T.SphereGeometry(7,12,8),0xffc253,32,202);for(let i=0;i<7;i++){const a=(i/6-0.5)*Math.PI;beam(g,[Math.sin(a)*9,151+Math.cos(a)*8,0],[Math.sin(a)*23,151+Math.cos(a)*23,0],1.5,0x6ca492)}}
if(index===8){box(g,680,7,34,0x526165,0,85);[-180,180].forEach(x=>{[-22,22].forEach(z=>box(g,12,180,12,red,x,90,z));[65,120,170].forEach(y=>box(g,12,8,50,red,x,y));});for(const z of [-22,22]){let prev=null;for(let x=-330;x<=330;x+=15){const y=100+80*Math.abs(Math.sin(x/360*Math.PI));if(prev)beam(g,prev,[x,y,z],2.6,red);beam(g,[x,85,z],[x,y,z],.8,red);prev=[x,y,z]}}}
return g;}
export function buildScenery(world,origin,destination,route,weatherCells=[]){const terrainHeight=(x,z)=>elevation(route,x,z);let seed=origin*1531+destination*93+11;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const terrainGeo=new T.PlaneGeometry(16000,20500,200,240);terrainGeo.rotateX(-Math.PI/2);terrainGeo.translate(0,0,-6500);const p=terrainGeo.attributes.position,colors=[];const color=new T.Color();for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);const geo=routePosition(route,x,z);const dry=Math.abs(geo.lat)<35&&Math.abs(geo.lat)>20; color.set(h<0?0xa7b99c:h>400?0x7d8b7b:h>180?0x476f43:dry?0x829c55:0x619448);color.multiplyScalar(.88+.12*Math.sin(x*.009)*Math.cos(z*.013));colors.push(color.r,color.g,color.b)}terrainGeo.setAttribute('color',new T.Float32BufferAttribute(colors,3));terrainGeo.computeVertexNormals();world.add(new T.Mesh(terrainGeo,new T.MeshStandardMaterial({vertexColors:true,roughness:1})));
const waterGeo=new T.PlaneGeometry(18000,22000,120,150);waterGeo.rotateX(-Math.PI/2);waterGeo.translate(0,-3,-6500);const waterMat=new T.MeshStandardMaterial({color:0x117caa,roughness:.3,metalness:.35});const waveTime={value:0};waterMat.onBeforeCompile=shader=>{shader.uniforms.waveTime=waveTime;shader.vertexShader='uniform float waveTime; varying vec3 oceanPos;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n transformed.y += sin(position.x * .018 + waveTime * 1.5) * .65 + sin(position.z * .026 + waveTime) * .45; oceanPos = position;');shader.fragmentShader='uniform float waveTime; varying vec3 oceanPos;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\n float ripple = pow(max(0.0, sin(oceanPos.x * .023 + sin(oceanPos.z * .019) * 2.0 + waveTime) * sin(oceanPos.z * .037 + cos(oceanPos.x * .013) + waveTime * .7)),8.0); float swell = sin(oceanPos.x * .0017 + sin(oceanPos.z * .002) + waveTime * .13); diffuseColor.rgb += vec3(.04,.10,.12) * ripple + vec3(.006,.015,.02) * swell;');};const water=new T.Mesh(waterGeo,waterMat);world.add(water);
function runway(z){box(world,160,1,1300,0x879d78,0,1,z);box(world,100,1.2,1100,0x38454c,0,2,z);for(let i=0;i<18;i++){box(world,3,.1,22,0xf0eee1,0,2.7,z+500-i*58);[-49,49].forEach(x=>{const lamp=part(world,new T.SphereGeometry(1.8,6,6),0xe6f5bc,x,3,z+500-i*58);lamp.material.emissive.set(0x94cf6b);})}for(let i=-3;i<=3;i++){if(i)box(world,5,.1,60,0xffffff,i*10,2.7,z+465)}box(world,110,25,170,0xd9ded3,-180,13,z+200);box(world,30,65,30,0xc2c9be,-180,33,z-80);box(world,44,18,44,0x638c9c,-180,72,z-80);}
runway(-120);runway((RUNWAY.start+RUNWAY.end)/2);
const buildingGeo=new T.BoxGeometry(1,1,1),buildingMat=new T.MeshStandardMaterial({roughness:.7}),buildings=new T.InstancedMesh(buildingGeo,buildingMat,650),dummy=new T.Object3D();for(let i=0;i<650;i++){const end=i>324,z=(end?-12700:-900)+(rand()-.5)*2500,x=(rand()>.5?1:-1)*(250+rand()*780),h=15+Math.pow(rand(),2)*170;dummy.position.set(x,terrainHeight(x,z)+h/2,z);dummy.scale.set(20+rand()*40,h,20+rand()*40);if(terrainHeight(x,z)<0)dummy.scale.setScalar(0);dummy.updateMatrix();buildings.setMatrixAt(i,dummy.matrix);buildings.setColorAt(i,new T.Color([0xe8dfcb,0xb1cccb,0x86aab7,0xcad2c2,0xdfb89b][i%5]));}world.add(buildings);
for(const z of [-900,-12700]){for(const x of [-500,-900,500,900])for(let j=0;j<12;j++){const zz=z-1100+j*200;if(terrainHeight(x,zz)>=0)box(world,12,.25,190,0x627067,x,terrainHeight(x,zz)+.5,zz)}}
// Agricultural patches and scattered villages only occur on dry land.
for(let i=0;i<150;i++){const x=(rand()-.5)*6500,z=-2200-rand()*9000,y=terrainHeight(x,z);if(y<0||y>120)continue;const patch=box(world,100+rand()*100,.3,80+rand()*150,[0x8fa55b,0x9fa46a,0x62874d,0xb5a477][i%4],x,y+.3,z);patch.rotation.y=rand()*.5;}
const trees=new T.InstancedMesh(new T.ConeGeometry(1,1,7),material(0x327748),900);for(let i=0;i<900;i++){const x=(rand()>.5?-1:1)*(850+rand()*2800),z=600-rand()*15000,h=18+rand()*22;dummy.position.set(x,terrainHeight(x,z)+h/2,z);dummy.scale.set(h*.35,h,h*.35);if(terrainHeight(x,z)<0)dummy.scale.setScalar(0);dummy.updateMatrix();trees.setMatrixAt(i,dummy.matrix);trees.setColorAt(i,new T.Color([0x3f884d,0x2e6e47,0x61964a][i%3]));}world.add(trees);
const landmarks=[];[[origin,-420,-850],[destination,420,-12850]].forEach(([id,x,z])=>{const g=landmark(id);g.position.set(x,terrainHeight(x,z),z);world.add(g);landmarks.push({group:g,name:LANDMARK_NAMES[id],x,y:g.position.y+330,z});});
// Soft radial billboards avoid hard opaque cloud intersections.
const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(64,64,8,64,64,64);gradient.addColorStop(0,'rgba(255,255,255,0.9)');gradient.addColorStop(.45,'rgba(255,255,255,0.65)');gradient.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);const texture=new T.CanvasTexture(canvas),clouds=[];for(let i=0;i<70;i++){const x=i<24?(rand()-.5)*1500:(rand()-.5)*7000,z=-1400-rand()*10000,y=550+rand()*450;clouds.push({x,y,z,r:160+rand()*100});for(let j=0;j<4;j++){const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,color:0xffffff,opacity:.65,depthWrite:false,fog:true}));sprite.position.set(x+(rand()-.5)*240,y+(rand()-.5)*90,z+(rand()-.5)*170);sprite.scale.set(420,240,1);world.add(sprite)}}// Guaranteed cloud crossings on the climb and descent.
for(const point of [WAYPOINTS[1],WAYPOINTS[5]]){clouds.push({...point,r:250});for(let j=0;j<6;j++){const sp=new T.Sprite(new T.SpriteMaterial({map:texture,opacity:.7,depthWrite:false}));sp.position.set(point.x+(rand()-.5)*220,point.y+(rand()-.5)*90,point.z+(rand()-.5)*160);sp.scale.set(500,290,1);world.add(sp)}}
const stormSprites=[];for(const cell of weatherCells){if(cell.type!=='storm')continue;for(let i=0;i<16;i++){const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,color:0x34465a,opacity:.6,depthWrite:false}));sprite.position.set(cell.x+(rand()-.5)*cell.width*1.5,cell.base+rand()*(cell.top-cell.base),cell.z+(rand()-.5)*cell.length*1.6);sprite.scale.set(700,400,1);world.add(sprite);stormSprites.push(sprite);}}
const boltGeo=new T.BufferGeometry().setFromPoints([new T.Vector3(0,600,0),new T.Vector3(-30,430,0),new T.Vector3(20,460,0),new T.Vector3(-10,180,0),new T.Vector3(25,210,0),new T.Vector3(0,0,0)]);const lightning=new T.Line(boltGeo,new T.LineBasicMaterial({color:0xd7e8ff}));lightning.visible=false;world.add(lightning);
return{clouds,landmarks,water,texture,waveTime,lightning,stormSprites};}
